325:    fn setup(&self) -> Result<()> {
326:        if !self.is_available()? {
327:            bail!("Podman is not installed. Please install podman first.");
328:        }
329:
330:        let output = Command::new("podman")
331:            .args(["info", "--format", "{{.Host.Security.Rootless}}"])
332:            .output()
333:            .context("Failed to check podman rootless mode")?;
334:
335:        let rootless = String::from_utf8_lossy(&output.stdout).trim() == "true";
336:        if !rootless {
337:            eprintln!("Warning: Podman is not running in rootless mode.");
338:            eprintln!("For security, please configure rootless podman.");
339:        }
