341:        self.ensure_image("nibble-sandbox:latest")?;
342:
343:        Ok(())
344:    }
345:
346:    fn spawn(
347:        &self,
348:        task_id: &str,
349:        repo_path: &Path,
350:        config: &SandboxConfig,
351:    ) -> Result<ContainerInfo> {
352:        self.ensure_image(&config.image)?;
353:
354:        let container_name = self.container_name(task_id);
355:        let repo_abs = repo_path
356:            .canonicalize()
357:            .context("Failed to resolve repo path")?;
358:
359:        let mut args = vec![
360:            "run".to_string(),
361:            "-d".to_string(),
362:            "--name".to_string(),
363:            container_name.clone(),
364:            "--hostname".to_string(),
365:            format!("agent-{}", &task_id[..8.min(task_id.len())]),
366:            "--network".to_string(),
367:            "host".to_string(),
368:            "-w".to_string(),
369:            container_working_dir(&repo_abs),
370:            // Map host uid/gid into the container so volume-mounted files
371:            // owned by the host user (e.g. ~/.claude) are accessible as node.
372:            "--userns=keep-id".to_string(),
373:        ];
374:
375:        if config.privileged {
376:            args.push("--privileged".to_string());
377:        }
378:
379:        // Restart policy:
380:        // - Default entrypoint (sleep infinity): --restart=always is safe because
381:        //   sleep only exits if killed (OOM, signal); restarting it is desirable
382:        //   after a host reboot.
383:        // - Custom entrypoint (e.g. hermes gateway): --restart=always creates a
384:        //   crash loop if PID 1 exits repeatedly (e.g. hermes not installed, OOM).
385:        //   Use --restart=on-failure:3 to limit restart attempts and avoid
386:        //   consuming host resources in a tight loop that triggers the OOM killer.
387:        if config.entrypoint.is_empty() {
388:            args.push("--restart=always".to_string());
389:        } else {
390:            args.push("--restart=on-failure:3".to_string());
391:        }
392:
393:        if let Some(cpu) = &config.cpu_limit {
394:            args.push("--cpus".to_string());
395:            args.push(cpu.clone());
396:        }
397:        if let Some(memory) = &config.memory_limit {
398:            args.push("--memory".to_string());
399:            args.push(memory.clone());
400:        }
401:
402:        // User-supplied env vars from config
403:        for (key, value) in &config.env_vars {
404:            args.push("-e".to_string());
405:            args.push(format!("{}={}", key, value));
406:        }
407:
408:        // Standard env vars
409:        args.push("-e".to_string());
410:        args.push(format!("AGENT_TASK_ID={}", task_id));
411:        args.push("-e".to_string());
412:        args.push("AGENT_INBOX_VERSION=1".to_string());
413:        args.push("-e".to_string());
414:        args.push("HOME=/home/node".to_string());
415:
416:        // Forward Anthropic API configuration from host if set
417:        if let Ok(api_key) = std::env::var("ANTHROPIC_API_KEY") {
418:            args.push("-e".to_string());
419:            args.push(format!("ANTHROPIC_API_KEY={}", api_key));
420:        }
421:        if let Ok(base_url) = std::env::var("ANTHROPIC_BASE_URL") {
422:            // Only forward host base URL if the sandbox config hasn't already
423:            // set one (e.g. via the privacy filter proxy).
424:            if !config.env_vars.contains_key("ANTHROPIC_BASE_URL") {
425:                args.push("-e".to_string());
426:                args.push(format!("ANTHROPIC_BASE_URL={}", base_url));
427:            }
428:        }
429:
430:        // Forward GitHub token from host so gh CLI is authenticated inside
431:        // the container. Set GITHUB_TOKEN in your host environment, e.g.
432:        //   export GITHUB_TOKEN=$(gh auth token)
433:        if let Ok(token) = std::env::var("GITHUB_TOKEN") {
434:            args.push("-e".to_string());
435:            args.push(format!("GITHUB_TOKEN={}", token));
436:        }
437:
438:        let cwd = container_working_dir(&repo_abs);
439:
440:        // Repo mount
441:        args.push("-v".to_string());
442:        args.push(format!("{}:{}:rw", repo_abs.display(), cwd));
443:
444:        // Shared dependency caches
445:        for (host_path, container_path) in self.get_cache_volumes()? {
446:            args.push("-v".to_string());
447:            args.push(format!("{}:{}", host_path, container_path));
448:        }
449:
450:        // Extra volumes from config
451:        for volume in &config.extra_volumes {
452:            args.push("-v".to_string());
453:            args.push(volume.clone());
454:        }
455:
456:        // Mount host's ~/.claude so the container shares auth, config, and hooks
457:        let home_dir = dirs::home_dir().context("Failed to get home directory")?;
458:
459:        // If the repo has a project-level .claude/settings.json, shadow it inside
460:        // the container with an empty file.  This prevents hooks defined there from
461:        // duplicating the global hooks already in ~/.claude/settings.json.
462:        let repo_claude_settings = repo_abs.join(".claude").join("settings.json");
463:        if repo_claude_settings.exists() {
464:            let empty_settings_path = home_dir
465:                .join(".nibble")
466:                .join("cache")
467:                .join("empty-claude-settings.json");
468:            if let Some(parent) = empty_settings_path.parent() {
469:                std::fs::create_dir_all(parent).ok();
470:            }
471:            if !empty_settings_path.exists() {
472:                std::fs::write(&empty_settings_path, b"{}").ok();
473:            }
474:            eprintln!("[sandbox] Shadowing repo .claude/settings.json to prevent hook duplication");
475:            args.push("-v".to_string());
476:            args.push(format!(
477:                "{}:{}/.claude/settings.json:ro",
478:                empty_settings_path.display(),
479:                cwd
480:            ));
481:        }
482:
483:        let claude_dir = home_dir.join(".claude");
484:        if claude_dir.exists() {
485:            args.push("-v".to_string());
486:            args.push(format!("{}:/home/node/.claude:rw", claude_dir.display()));
487:            args.push("-e".to_string());
488:            args.push("CLAUDE_CONFIG_DIR=/home/node/.claude".to_string());
489:        }
490:
491:        // Mount the nibble binary so hooks inside the container can call it.
492:        // Prefer the musl (statically linked) build so it works regardless of
493:        // the container's glibc version. Fall back to the host binary.
494:        let musl_bin = home_dir.join(".local/bin/nibble-musl");
495:        let host_bin = home_dir.join(".local/bin/nibble");
496:        let nibble_bin = if musl_bin.exists() {
497:            musl_bin
498:        } else {
499:            host_bin
500:        };
501:        if nibble_bin.exists() {
502:            args.push("-v".to_string());
503:            args.push(format!("{}:/usr/local/bin/nibble:ro", nibble_bin.display()));
504:        }
505:
506:        // Mount nibble config (Telegram token etc.) so hooks can send notifications.
507:        let nibble_dir = home_dir.join(".nibble");
508:        if nibble_dir.exists() {
509:            args.push("-v".to_string());
510:            args.push(format!("{}:/home/node/.nibble:rw", nibble_dir.display()));
511:        }
512:
513:        // Mount host gitconfig read-only so git identity and settings carry over.
514:        let gitconfig = home_dir.join(".gitconfig");
515:        if gitconfig.exists() {
516:            args.push("-v".to_string());
517:            args.push(format!("{}:/home/node/.gitconfig:ro", gitconfig.display()));
518:        }
519:
520:        args.push(config.image.clone());
521:
522:        // Container PID 1: use custom entrypoint if provided, otherwise sleep infinity.
523:        // INV-1: For Hermes sandboxes, the gateway is PID 1 so the container stops if it crashes.
524:        if config.entrypoint.is_empty() {
525:            args.push("sleep".to_string());
526:            args.push("infinity".to_string());
527:        } else {
528:            args.extend(config.entrypoint.iter().cloned());
529:        }
530:
531:        let output = Command::new("podman")
532:            .args(&args)
533:            .output()
534:            .context("Failed to spawn container")?;
535:
536:        if !output.status.success() {
537:            let stderr = String::from_utf8_lossy(&output.stderr);
538:            bail!("Failed to spawn container: {}", stderr);
539:        }
540:
541:        let container_id = String::from_utf8_lossy(&output.stdout).trim().to_string();
542:
543:        let inspect_output = Command::new("podman")
544:            .args(["inspect", &container_name])
545:            .output()
546:            .context("Failed to inspect container")?;
547:
548:        let info =
549:            self.parse_container_info(String::from_utf8_lossy(&inspect_output.stdout).as_ref())?;
550:
551:        println!(
552:            "Container '{}' started (ID: {})",
553:            container_name,
554:            &container_id[..12.min(container_id.len())]
555:        );
556:
557:        Ok(info)
558:    }
559:
560:    fn start(&self, container_id: &str) -> Result<()> {
561:        let output = Command::new("podman")
562:            .args(["start", container_id])
563:            .output()
564:            .context("Failed to start container")?;
565:
